```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
using namespace std;

int main() {
    ifstream plik("pracownicy.txt");
    map<string, int> maxPensja;
    map<string, string> maxImie;
    string imie, dzial;
    int pensja;
    while (plik >> imie >> dzial >> pensja) {
        if (maxPensja.find(dzial) == maxPensja.end() || pensja > maxPensja[dzial]) {
            maxPensja[dzial] = pensja;
            maxImie[dzial] = imie;
        }
    }

    cout << "a) Najwyzsza pensja w dziale:" << endl;
    for (auto &p : maxPensja) {
        cout << "   " << p.first << ": " << p.second << endl;
    }

    cout << endl << "b) Pracownik z najwyzsza pensja:" << endl;
    for (auto &p : maxPensja) {
        cout << "   " << p.first << ": " << maxImie[p.first] << " (" << p.second << ")" << endl;
    }
    return 0;
}
```

